"""Exploratory tables for the Mac session (2026-10-17): cross-platform repeatability (box CPU vs Apple MPS), the deterministic-classifier group
including the exploratory T6 encoder schema classifier (GLiNER2.5-Decide), and the matched decision-model comparison (T7 Clef-flash vs gpt-6-luna,
same first 200 items, official + 30 VALID sets, UQ_TEST_SIZE = 100, same Design-A splits). Decision models are never compared with encoders or
generative-logprob LLMs. Output: results/mac_tables.md (+ results/mac_numbers.json)."""
import json, os, glob
import numpy as np
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "results"); C = f"{R}/cells"
DSN = {"agnews": "AG News", "bbc2025": "BBC 2024-25", "sst2": "SST-2", "dbpedia": "DBpedia-14", "massive": "MASSIVE-18"}; DS = list(DSN)
f2 = lambda x: "–" if x is None or not np.isfinite(x) else f"{x:.2f}"; f3 = lambda x: "–" if x is None or not np.isfinite(x) else f"{x:.3f}"
ci = lambda c, f=f3: f"[{f(c[0])}, {f(c[1])}]"
cells = {os.path.basename(f)[:-5]: json.load(open(f)) for f in glob.glob(f"{C}/*.json") if os.path.basename(f)[:-5].count("__") == 2}
out = []; P = out.append; NUM = {}
P("# Mac-session tables (auto-generated by src/mac_tables.py; exploratory)\n")
x = sorted(glob.glob(f"{R}/xplat_*.json"))
if x:
    P("## Table M1. Cross-platform repeatability (hardware/backend change): box CPU vs Apple M5 MPS, fp32, same pair order and batches\n")
    P("| cell | N × strings | max abs Δlogit | max abs Δp (all sets) | argmax flips | mean share of test items with changed LAC set | max (one split) | sets with any LAC change | max Δ mean set size | Mac s / box s |\n|---|---|---|---|---|---|---|---|---|---|")
    for f in x:
        z = json.load(open(f)); s = z["summary"]; NUM[os.path.basename(f)] = s
        P(f"| {z['cell']} | {z['N']} × {z['n_strings']} | {z['max_abs_dlogit']:.1e} | {s['max_dp']:.1e} | {s['argmax_flip_items_total']} | {s['lac_set_changed_mean_over_sets']:.1e} | {s['lac_set_changed_max_split']:.4f} | {s['sets_with_any_lac_change']}/{s['n_sets']} | {s['max_d_mean_set_size']:.4f} | {z['mac_meta']['seconds']:.0f} / {z['box_meta']['seconds']:.0f} |")
def row(k, v, n):
    b = v["floor"].get(f"A|lac|valid|{n}")
    if not b: return None
    s = b["set_size"]; c = b["coverage"]
    return s, c
P("\n## Table M2. Deterministic-classifier group (T1 NLI, T2 bi-encoder, T6 GLiNER2.5-Decide exploratory), n_cal = 250, LAC, α = 0.10\n")
P("| type | dataset | model | N | σ_wording [CI] | σ_split | ratio | wording share [CI] | config-shift mean coverage (min) |\n|---|---|---|---|---|---|---|---|---|")
det = {k: v for k, v in cells.items() if v["kind"] in ("nli", "bienc", "schema") and not any(t in k for t in ("_tau", "_rawll", "_sub"))}
TN = {"nli": "T1", "bienc": "T2", "schema": "T6 (expl.)"}
NUM["det"] = {}
for k in sorted(det, key=lambda k: (["nli", "bienc", "schema"].index(det[k]["kind"]), DS.index(det[k]["dataset"]), det[k]["model"])):
    v = det[k]; n = 250 if 250 in v["n_grid"] else v["n_grid"][0]; s = v["floor"][f"A|lac|valid|{n}"]["set_size"]
    cv = [r["coverage_mean"] for r in v.get("config_shift_official_to_valid", [])]; mc = float(np.mean(cv)) if cv else None; mn = float(min(cv)) if cv else None
    NUM["det"][k] = {"sd_w": s["sd_w"], "sd_s": s["sd_s"], "ratio": s["ratio_w_s"], "share_w": s["share_w"], "cs_mean": mc, "cs_min": mn}
    P(f"| {TN[v['kind']]} | {DSN[v['dataset']]} | {v['model']} | {v['N']} | {f3(s['sd_w'])} {ci(s['ci_sd_w'])} | {f3(s['sd_s'])} | {f2(s['ratio_w_s'])} | {f2(s['share_w'])} {ci(s['ci_share_w'], f2)} | {f3(mc) if mc is not None else '–'} ({f3(mn) if mn is not None else '–'}) |")
sub = {k: v for k, v in cells.items() if k.endswith("_sub200") and v["kind"] in ("api", "decision")}
if sub:
    P("\n## Table M3. Decision-model group, matched design: Clef-flash (T7) vs gpt-6-luna (T5 Decisions API), same first 200 items, official + 30 VALID sets, test 100, n_cal = 100, LAC, α = 0.10\n")
    P("| dataset | model | acc official | acc VALID mean | mean set size | σ_wording [CI] | σ_split | ratio | wording share [CI] |\n|---|---|---|---|---|---|---|---|---|")
    NUM["decision_sub200"] = {}
    for k in sorted(sub, key=lambda k: (DS.index(sub[k]["dataset"]), sub[k]["kind"])):
        v = sub[k]; n = 100 if 100 in v["n_grid"] else v["n_grid"][-1]; s = v["floor"][f"A|lac|valid|{n}"]["set_size"]
        va = [v["point"][q]["accuracy"] for q in v["point"] if q.startswith("valid_")]
        NUM["decision_sub200"][k] = {"n": n, "acc_off": v["point"]["official"]["accuracy"], "acc_valid": float(np.mean(va)), "sd_w": s["sd_w"], "sd_s": s["sd_s"], "ratio": s["ratio_w_s"], "share_w": s["share_w"]}
        P(f"| {DSN[v['dataset']]} | {v['model']} | {f3(v['point']['official']['accuracy'])} | {f3(np.mean(va))} | {f3(s['mean'])} | {f3(s['sd_w'])} {ci(s['ci_sd_w'])} | {f3(s['sd_s'])} | {f2(s['ratio_w_s'])} | {f2(s['share_w'])} {ci(s['ci_share_w'], f2)} |")
open(f"{R}/mac_tables.md", "w").write("\n".join(out) + "\n"); json.dump(NUM, open(f"{R}/mac_numbers.json", "w"), indent=1, default=float); print("WROTE results/mac_tables.md")
